#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = (1LL << 62);

struct Edge {
    int to;
    ll w;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    ll X;
    cin >> N >> M >> X;

    // room type:
    // 0 = cold, 1 = comfortable, 2 = hot
    vector<int> type(N + 1);
    for (int i = 1; i <= N; i++) {
        int a;
        cin >> a;
        type[i] = a;
    }

    vector<vector<Edge>> g(N + 1);
    for (int i = 0; i < M; i++) {
        int u, v;
        ll d;
        cin >> u >> v >> d;
        g[u].push_back({v, d});
        g[v].push_back({u, d});
    }

    /*
      State compression:

      We only need to remember the "dangerous recent extreme":
      - if the last extreme room visited was cold and it was t minutes ago (< X),
        then entering a hot room is forbidden.
      - if the last extreme room visited was hot and it was t minutes ago (< X),
        then entering a cold room is forbidden.
      - comfortable rooms do not reset this; time since last extreme just increases.
      - visiting cold resets to cold with timer 0.
      - visiting hot resets to hot with timer 0.
      - once timer >= X, restriction disappears; exact larger value is irrelevant.

      So state = (room, mode, rem)
      mode:
        0 = no active restriction (timer >= X, or none)
        1 = last extreme was cold, and rem in [1..X] means still for rem more minutes cannot enter hot
        2 = last extreme was hot,  and rem in [1..X] means still for rem more minutes cannot enter cold

      rem is capped into [0..X], where 0 only used with mode 0.
      For mode 1 or 2, rem is in [1..X].
      After traversing edge of length w: rem' = max(0, rem - w), and if becomes 0 => mode 0.
    */

    // Number states per node: 1 + X + X
    // index:
    // mode 0 => 0
    // mode 1, rem r => r
    // mode 2, rem r => X + r
    auto idx = [X](int mode, ll rem) -> int {
        if (mode == 0) return 0;
        if (mode == 1) return (int)rem;
        return (int)(X + rem);
    };

    int S = 1 + (int)X + (int)X;
    vector<vector<ll>> dist(N + 1, vector<ll>(S, INF));

    // start in room 1, which is cold
    int startIdx = idx(1, X);
    dist[1][startIdx] = 0;

    using T = tuple<ll, int, int>; // dist, node, stateIndex
    priority_queue<T, vector<T>, greater<T>> pq;
    pq.push({0, 1, startIdx});

    while (!pq.empty()) {
        auto [cd, u, si] = pq.top();
        pq.pop();
        if (cd != dist[u][si]) continue;

        int mode;
        ll rem;
        if (si == 0) {
            mode = 0;
            rem = 0;
        } else if (si <= X) {
            mode = 1;
            rem = si;
        } else {
            mode = 2;
            rem = si - X;
        }

        for (auto &e : g[u]) {
            int v = e.to;
            ll w = e.w;

            // advance timer through corridor
            int nmode = mode;
            ll nrem = rem;
            if (nmode != 0) {
                if (w >= nrem) {
                    nmode = 0;
                    nrem = 0;
                } else {
                    nrem -= w;
                }
            }

            // check entering room v
            if (type[v] == 0) { // cold
                if (nmode == 2) continue; // recently hot
                nmode = 1;
                nrem = X;
            } else if (type[v] == 2) { // hot
                if (nmode == 1) continue; // recently cold
                nmode = 2;
                nrem = X;
            } else {
                // comfortable: keep current state
            }

            int nsi = idx(nmode, nrem);
            ll nd = cd + w;
            if (nd < dist[v][nsi]) {
                dist[v][nsi] = nd;
                pq.push({nd, v, nsi});
            }
        }
    }

    ll ans = INF;
    for (int s = 0; s < S; s++) ans = min(ans, dist[N][s]);

    if (ans == INF) cout << -1 << '\n';
    else cout << ans << '\n';

    return 0;
}

