#define INF 1000000000000000000LL

typedef long long ll;

typedef struct Edge {
    int to, next;
    ll w;
} Edge;

Edge edges[MAXM * 2];
int head[MAXN], edge_cnt;
int temp[MAXN]; // 0: cold, 1: comfortable, 2: hot
ll dist[MAXN][3]; // dist[node][last_temp_type] where last_temp_type: 0=cold, 1=comfortable, 2=hot
int n, m;
ll X;

void add_edge(int u, int v, ll w) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].w = w;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

typedef struct Node {
    int v, type;
    ll d;
} Node;

typedef struct Heap {
    Node *arr;
    int size, cap;
} Heap;

Heap* create_heap(int cap) {
    Heap *h = (Heap*)malloc(sizeof(Heap));
    h->arr = (Node*)malloc(cap * sizeof(Node));
    h->size = 0;
    h->cap = cap;
    return h;
}

void swap(Node *a, Node *b) {
    Node t = *a;
    *a = *b;
    *b = t;
}

void push(Heap *h, Node node) {
    if (h->size == h->cap) {
        h->cap *= 2;
        h->arr = (Node*)realloc(h->arr, h->cap * sizeof(Node));
    }
    int i = h->size++;
    h->arr[i] = node;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (h->arr[p].d <= h->arr[i].d) break;
        swap(&h->arr[p], &h->arr[i]);
        i = p;
    }
}

Node pop(Heap *h) {
    Node ret = h->arr[0];
    h->arr[0] = h->arr[--h->size];
    int i = 0;
    while (1) {
        int left = 2 * i + 1;
        int right = 2 * i + 2;
        int smallest = i;
        if (left < h->size && h->arr[left].d < h->arr[smallest].d) smallest = left;
        if (right < h->size && h->arr[right].d < h->arr[smallest].d) smallest = right;
        if (smallest == i) break;
        swap(&h->arr[i], &h->arr[smallest]);
        i = smallest;
    }
    return ret;
}

int empty(Heap *h) {
    return h->size == 0;
}

int can_go(int from_type, int to_type, ll time_diff) {
    // from_type: type of room we are leaving (the one we just spent time in)
    // to_type: type of room we are entering
    if (from_type == 0 && to_type == 2) {
        // cold -> hot: need at least X time since leaving cold
        return time_diff >= X;
    }
    if (from_type == 2 && to_type == 0) {
        // hot -> cold: need at least X time since leaving hot
        return time_diff >= X;
    }
    // comfortable or same type: always allowed
    return 1;
}

int main() {
    scanf("%d %d %lld", &n, &m, &X);
    for (int i = 1; i <= n; i++) {
        scanf("%d", &temp[i]);
    }
    memset(head, -1, sizeof(head));
    edge_cnt = 0;
    for (int i = 0; i < m; i++) {
        int a, b;
        ll c;
        scanf("%d %d %lld", &a, &b, &c);
        add_edge(a, b, c);
        add_edge(b, a, c);
    }

    // Initialize distances
    for (int i = 1; i <= n; i++) {
        for (int j = 0; j < 3; j++) {
            dist[i][j] = INF;
        }
    }

    // Start at room 1 (cold). We consider the "last type" as cold (0) because we just left cold.
    // But we are at room 1 initially, so we can treat it as if we "left" a cold room at time 0.
    dist[1][0] = 0; // type 0 means last visited room was cold

    Heap *h = create_heap(1000000);
    push(h, (Node){1, 0, 0});

    while (!empty(h)) {
        Node cur = pop(h);
        int u = cur.v;
        int last_type = cur.type;
        ll d = cur.d;
        if (d != dist[u][last_type]) continue;

        // If we reached room N, we can stop (but we need to consider that we might arrive with different last_type)
        // Since Dijkstra processes in increasing distance, first time we pop N we have answer.
        if (u == n) {
            printf("%lld\n", d);
            return 0;
        }

        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            ll w = edges[e].w;
            int next_type = temp[v]; // type of room we are entering

            // Check if we can enter v given that we are leaving a room of type last_type
            if (!can_go(last_type, next_type, w)) continue; // time difference is w (time to travel)

            ll nd = d + w;
            // The "last type" for the next state is the type of room we just entered (v)
            if (nd < dist[v][next_type]) {
                dist[v][next_type] = nd;
                push(h, (Node){v, next_type, nd});
            }
        }
    }

    // If we never reached N
    printf("-1\n");
    return 0;
}

