typedef long long ll;

typedef struct Edge {
    int to;
    int w;
    int next;
} Edge;

typedef struct Node {
    ll dist;
    int v;
} Node;

typedef struct Heap {
    Node *a;
    int size;
    int cap;
} Heap;

static void heap_init(Heap *h, int cap) {
    h->a = (Node*)malloc(sizeof(Node) * (cap + 1));
    h->size = 0;
    h->cap = cap;
}

static void heap_push(Heap *h, ll dist, int v) {
    if (h->size + 1 > h->cap) {
        h->cap *= 2;
        h->a = (Node*)realloc(h->a, sizeof(Node) * (h->cap + 1));
    }
    int i = ++h->size;
    while (i > 1 && h->a[i / 2].dist > dist) {
        h->a[i] = h->a[i / 2];
        i /= 2;
    }
    h->a[i].dist = dist;
    h->a[i].v = v;
}

static Node heap_pop(Heap *h) {
    Node ret = h->a[1];
    Node last = h->a[h->size--];
    int i = 1;
    while (i * 2 <= h->size) {
        int c = i * 2;
        if (c + 1 <= h->size && h->a[c + 1].dist < h->a[c].dist) c++;
        if (h->a[c].dist >= last.dist) break;
        h->a[i] = h->a[c];
        i = c;
    }
    h->a[i] = last;
    return ret;
}

