                        int nid = (nr == 0 ? ID(to, 0, 0) : ID(to, 1, nr));
                        if (nd < dist[nid]) {
                            dist[nid] = nd;
                            heap_push(&hp, nd, nid);
                        }
                    } else {
                        int nr = XX - w;
                        if (nr < 0) nr = 0;
                        int nid = (nr == 0 ? ID(to, 0, 0) : ID(to, 2, nr));
                        if (nd < dist[nid]) {
                            dist[nid] = nd;
                            heap_push(&hp, nd, nid);
                        }
                    }
                } else {
                    if (type[to] == 2) continue;
                    if (type[to] == 0) {
                        int nid = ID(to, 1, rem - w);
                        if (nd < dist[nid]) {
                            dist[nid] = nd;
                            heap_push(&hp, nd, nid);
                        }
                    } else {
                        int nr = XX - w;
                        if (nr < 0) nr = 0;
                        int nid = (nr == 0 ? ID(to, 0, 0) : ID(to, 1, nr));
                        if (nd < dist[nid]) {
                            dist[nid] = nd;
                            heap_push(&hp, nd, nid);
                        }
                    }
                }
            } else {
                if (w >= rem) {
                    if (type[to] == 0) {
                        int nid = ID(to, 0, 0);
                        if (nd < dist[nid]) {
                            dist[nid] = nd;
                            heap_push(&hp, nd, nid);
                        }
                    } else if (type[to] == 1) {
                        int nr = XX - w;
                        if (nr < 0) nr = 0;
                        int nid = (nr == 0 ? ID(to, 0, 0) : ID(to, 1, nr));
                        if (nd < dist[nid]) {
                            dist[nid] = nd;
                            heap_push(&hp, nd, nid);
                        }
                    } else {
                        int nr = XX - w;
                        if (nr < 0) nr = 0;
                        int nid = (nr == 0 ? ID(to, 0, 0) : ID(to, 2, nr));
                        if (nd < dist[nid]) {
                            dist[nid] = nd;
                            heap_push(&hp, nd, nid);
                        }
                    }
                } else {
                    if (type[to] == 1) continue;
                    if (type[to] == 0) {
                        int nid = ID(to, 2, rem - w);
                        if (nd < dist[nid]) {
                            dist[nid] = nd;
                            heap_push(&hp, nd, nid);
                        }
                    } else {
                        int nr = XX - w;
                        if (nr < 0) nr = 0;
                        int nid = (nr == 0 ? ID(to, 0, 0) : ID(to, 2, nr));
                        if (nd < dist[nid]) {
                            dist[nid] = nd;
                            heap_push(&hp, nd, nid);
                        }
                    }
                }
            }
        }
    }

    ll ans = INF;
    for (int off = 0; off < states_per_room; off++) {
        int id = (N - 1) * states_per_room + off;
        if (dist[id] < ans) ans = dist[id];
    }

    if (ans == INF) printf("-1\n");
    else printf("%lld\n", ans);

    return 0;
}

import java.io.*;
import java.util.*;

public class Main {
    static class Edge {
        int to, time;
        Edge(int to, int time) {
            this.to = to;
            this.time = time;
        }
    }

    static class State implements Comparable<State> {
        int room;
        long time;
        int lastType; // 0 = cold, 1 = comfortable, 2 = hot

        State(int room, long time, int lastType) {
            this.room = room;
            this.time = time;
            this.lastType = lastType;
        }

        public int compareTo(State other) {
            return Long.compare(this.time, other.time);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());
        int X = Integer.parseInt(st.nextToken());

        int[] type = new int[N + 1];
        st = new StringTokenizer(br.readLine());
        for (int i = 1; i <= N; i++) {
            type[i] = Integer.parseInt(st.nextToken());
        }

        List<Edge>[] graph = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            int c = Integer.parseInt(st.nextToken());
            graph[a].add(new Edge(b, c));
            graph[b].add(new Edge(a, c));
        }

        // dist[room][lastType] = minimum time
        long[][] dist = new long[N + 1][3];
        for (int i = 0; i <= N; i++) {
            Arrays.fill(dist[i], Long.MAX_VALUE);
        }

        PriorityQueue<State> pq = new PriorityQueue<>();
        // Start at room 1, type is cold (0)
        dist[1][0] = 0;
        pq.offer(new State(1, 0, 0));

        while (!pq.isEmpty()) {
            State cur = pq.poll();
            int u = cur.room;
            long t = cur.time;
            int lastType = cur.lastType;

            if (t != dist[u][lastType]) continue;
            if (u == N) {
                System.out.println(t);
                return;
            }

            for (Edge e : graph[u]) {
                int v = e.to;
                int travelTime = e.time;
                int nextType = type[v];
                long newTime = t + travelTime;

                // Check constraint: cannot enter too hot if left cold within X, and vice versa
                if (lastType == 0 && nextType == 2) {
                    // Left cold, entering hot: need at least X minutes since leaving cold
                    // lastType=0 means we are in a cold room, so we need to check if we just left cold
                    // Actually the constraint: cannot enter hot room within X minutes of leaving cold room
                    // Since lastType is the type of the room we are currently in (which is cold),
                    // we are leaving cold now, so entering hot is forbidden if travelTime < X
                    // But the constraint says: cannot enter a too hot room within X minutes of leaving a too cold room.
                    // So if we go directly from cold to hot, the time since leaving cold is travelTime.
                    // If travelTime < X, it's forbidden.
                    if (travelTime < X) continue;
                } else if (lastType == 2 && nextType == 0) {
                    // Left hot, entering cold: need at least X minutes
                    if (travelTime < X) continue;
                }

                // If we are staying in same type or going to comfortable, no restriction
                if (newTime < dist[v][nextType]) {
                    dist[v][nextType] = newTime;
                    pq.offer(new State(v, newTime, nextType));
                }
            }
        }

        // If unreachable
        System.out.println(-1);
    }
}

