import java.io.*;
import java.util.*;

/*
 * JOI Snake escape
 *
 * State graph shortest path.
 *
 * Room types:
 *   0 = cold
 *   1 = comfortable
 *   2 = hot
 *
 * Constraint:
 * After leaving a cold room, JOI cannot enter a hot room for X minutes.
 * After leaving a hot room, JOI cannot enter a cold room for X minutes.
 *
 * We keep, for each position, a "temperature memory" state:
 *   - last extreme side currently relevant: cold-side or hot-side
 *   - elapsed time since leaving that side, capped at X
 *
 * More precisely, states are:
 *   C(t): the last extreme room on the path affecting restriction is cold,
 *         and t minutes (0..X) have passed since leaving that cold room,
 *         with t capped at X.
 *   H(t): analogous for hot.
 *
 * If we are in a cold room, state becomes C(0).
 * If we are in a hot room, state becomes H(0).
 * If we move through comfortable rooms for w minutes:
 *   C(t) -> C(min(X, t+w))
 *   H(t) -> H(min(X, t+w))
 * Entering opposite extreme is allowed only when timer == X.
 *
 * Number of states per room: 2*(X+1), which is feasible for the original constraints.
 * Run Dijkstra on expanded graph.
 */

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Edge {
        int to, w;
        Edge(int to, int w) {
            this.to = to;
            this.w = w;
        }
    }

    static class Node implements Comparable<Node> {
        long dist;
        int room, side, t; // side: 0 cold-memory, 1 hot-memory
        Node(long dist, int room, int side, int t) {
            this.dist = dist;
            this.room = room;
            this.side = side;
            this.t = t;
        }
        public int compareTo(Node o) {
            return Long.compare(this.dist, o.dist);
        }
    }

    static int advance(int t, int w, int X) {
        long v = (long)t + w;
        return v >= X ? X : (int)v;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();
        int X = fs.nextInt();

        int[] type = new int[N + 1];
        for (int i = 1; i <= N; i++) {
            type[i] = fs.nextInt();
        }

        List<Edge>[] g = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < M; i++) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            int c = fs.nextInt();
            g[a].add(new Edge(b, c));
            g[b].add(new Edge(a, c));
        }

        final long INF = Long.MAX_VALUE / 4;
        long[][][] dist = new long[N + 1][2][X + 1];
        for (int i = 1; i <= N; i++) {
            for (int s = 0; s < 2; s++) {
                Arrays.fill(dist[i][s], INF);
            }
        }

        PriorityQueue<Node> pq = new PriorityQueue<>();

        // Room 1 is guaranteed cold.
        dist[1][0][0] = 0;
        pq.add(new Node(0, 1, 0, 0));

        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            long cd = cur.dist;
            int v = cur.room, side = cur.side, t = cur.t;
            if (cd != dist[v][side][t]) continue;

            for (Edge e : g[v]) {
                int u = e.to;
                int w = e.w;

                int ntSide, nt;

                if (type[u] == 1) { // comfortable
                    ntSide = side;
                    nt = advance(t, w, X);
                } else if (type[u] == 0) { // cold
                    if (side == 1 && t < X) continue; // from hot too recently
                    ntSide = 0;
                    nt = 0;
                } else { // hot
                    if (side == 0 && t < X) continue; // from cold too recently
                    ntSide = 1;
                    nt = 0;
                }

                long nd = cd + w;
                if (nd < dist[u][ntSide][nt]) {
                    dist[u][ntSide][nt] = nd;
                    pq.add(new Node(nd, u, ntSide, nt));
                }
            }
        }

        long ans = INF;
        for (int s = 0; s < 2; s++) {
            for (int t = 0; t <= X; t++) {
                ans = Math.min(ans, dist[N][s][t]);
            }
        }

        System.out.println(ans >= INF ? -1 : ans);
    }
}
